import{_ as a,o as i,c as n,ai as l}from"./chunks/framework.Ai2o9gNv.js";const c=JSON.parse('{"title":"23-尾随lambda","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/23-尾随lambda/23-尾随lambda.md","filePath":"仓颉入门到实战/23-尾随lambda/23-尾随lambda.md","lastUpdated":1735170666000,"__rawMarkdown":"# 23-尾随lambda\\n\\n尾随 lambda 可以使函数的调用看起来像是语言内置的语法一样，增加语言的可扩展性。\\n\\n当函数最后一个形参是函数类型，并且函数调用对应的实参是 lambda 时，我们可以使用尾随 lambda 语法，将 lambda 放在函数调用的尾部，圆括号外面。\\n\\n例如，下例中我们定义了一个 `myIf` 函数，它的第一个参数是 `Bool` 类型，第二个参数是函数类型。当第一个参数的值为 `true` 时，返回第二个参数调用后的值，否则返回 `0`。调用 `myIf` 时可以像普通函数一样调用，也可以使用尾随 lambda 的方式调用。\\n\\n```javascript\\nfunc myIf(a: Bool, fn: () -> Int64) {\\n    if(a) {\\n        fn()\\n    } else {\\n        0\\n    }\\n}\\n\\nfunc test() {\\n    myIf(true, { => 100 }) // General function call\\n\\n    myIf(true) {        // Trailing closure call\\n        100\\n    }\\n}\\n```\\n\\n当函数调用有且只有一个 lambda 实参时，我们还可以省略 `()`，只写 lambda。\\n\\n示例：\\n\\n```javascript\\nfunc f(fn: (Int64) -> Int64) { fn(1) }\\n\\nfunc test() {\\n    f { i => i * i }\\n}\\n```"}'),p={name:"仓颉入门到实战/23-尾随lambda/23-尾随lambda.md"};function e(t,s,h,k,r,d){return i(),n("div",null,[...s[0]||(s[0]=[l("",8)])])}const b=a(p,[["render",e]]);export{c as __pageData,b as default};
